                edge.reason = PairReason::CompetingCompanyAnchors;
                continue;
            }
            let left = self.group[&edge.left_funder_id];
            let right = self.group[&edge.right_funder_id];
            let ids = self.members[left]
                .union(&self.members[right])
                .cloned()
                .collect::<BTreeSet<_>>();
